package com.infinitylibrary.builder;

import com.infinitylibrary.InfinityLibraryPlugin;
import com.infinitylibrary.model.*;
import org.bukkit.*;
import org.bukkit.block.Block;
import org.bukkit.entity.Player;
import org.bukkit.event.block.Action;
import org.bukkit.inventory.ItemStack;
import java.util.*;

/** Shared server-side authoring state for vanilla wands and the optional Fabric companion. */
public final class AuthoringManager {
    public static final List<String> TOOLS=List.of("room","connection","decoration","diversity","diversity_connection","variation","shelf","table","seat");
    public record Box(String kind,String label,Vector3i min,Vector3i max,int color){}
    private static final class State {long revision;String category="general",selected="";Vector3i first;final List<RoomRegion> regions=new ArrayList<>();final Deque<Runnable> undo=new ArrayDeque<>(),redo=new ArrayDeque<>();}
    private record Mark(String world,String kind,Vector3i min,Vector3i max){}
    private final InfinityLibraryPlugin plugin;private final Map<UUID,State> states=new HashMap<>();private final Map<UUID,List<Mark>> generated=new HashMap<>();private final List<Mark> applied=new ArrayList<>();
    public AuthoringManager(InfinityLibraryPlugin p){plugin=p;var y=com.infinitylibrary.community.AtomicYaml.read(p.getDataFolder().toPath().resolve("builder-regions.yml"));var root=y.getConfigurationSection("regions");if(root!=null)for(String id:root.getKeys(false)){var section=root.getConfigurationSection(id);applied.add(new Mark(section.getString("world"),section.getString("kind"),Vector3i.read(section.getConfigurationSection("min")),Vector3i.read(section.getConfigurationSection("max"))));}}
    private void saveApplied(){var y=new org.bukkit.configuration.file.YamlConfiguration();int index=0;for(var m:applied){var s=y.createSection("regions.r_"+(index++));s.set("world",m.world());s.set("kind",m.kind());m.min().write(s.createSection("min"));m.max().write(s.createSection("max"));}com.infinitylibrary.community.AtomicYaml.write(plugin.getDataFolder().toPath().resolve("builder-regions.yml"),y);}
    public void clearGenerated(){generated.clear();}
    private State state(Player p){return states.computeIfAbsent(p.getUniqueId(),id->new State());}
    public long revision(Player p){return state(p).revision;}
    public void changed(Player p){state(p).revision++;}
    public void select(Player p,String id){admin(p);plugin.getRoomManager().getActive(id).orElseThrow(()->new IllegalArgumentException("Active room not found."));state(p).selected=id;changed(p);}
    public String selected(Player p){return state(p).selected;}
    public boolean canUndo(Player p){return !state(p).undo.isEmpty();}public boolean canRedo(Player p){return !state(p).redo.isEmpty();}
    private void admin(Player p){if(!p.hasPermission("infinitylibrary.admin"))throw new IllegalArgumentException("Builder tools require infinitylibrary.admin.");}
    public String tool(Player p){var item=p.getInventory().getItemInMainHand();String kind=plugin.getDiversityManager().wandKind(item);if(kind!=null)return kind;if(plugin.getPropManager().isWand(item))return "decoration";return plugin.getSelectionManager().wandKind(item);}
    public String prompt(Player p){String tool=tool(p);if(tool==null)return "Choose a tool in the builder editor. Left: first corner · Right: second corner";if(tool.equals("room"))return "Room bounds · Left: first corner · Right: second corner";String phase=tool.equals("diversity")?" "+plugin.getDiversityManager().phase(p):"";return tool+phase+" · Left: first corner/restart · Right: finish · Undo/Cancel in editor";}
    public List<RoomRegion> regions(Player p){return List.copyOf(state(p).regions);}
    public void category(Player p,String category){admin(p);if(!category.matches("[a-z0-9_*-]{1,64}"))throw new IllegalArgumentException("Category needs lowercase letters/digits/_/- or *.");state(p).category=category;changed(p);}
    public void activate(Player p,String kind){admin(p);if(!TOOLS.contains(kind))throw new IllegalArgumentException("Unknown builder tool.");if(kind.equals("diversity_connection")){p.sendMessage("Choose an area, variant and direction with /il diversityconnection first.");return;}ItemStack item=switch(kind){case "room"->plugin.getSelectionManager().createWand();case "connection"->plugin.getSelectionManager().createConnectionWand();case "variation"->plugin.getSelectionManager().createVariationWand();case "shelf"->plugin.getSelectionManager().createBookshelfCategoryWand();case "table"->plugin.getSelectionManager().createReadingTableWand();case "seat"->plugin.getSelectionManager().createReadingSeatWand();case "decoration"->plugin.getPropManager().wand();default->plugin.getDiversityManager().wand();};var meta=item.getItemMeta();meta.setLore(List.of("§7Left-click: first corner / restart","§7Right-click: second corner / finish","§7/il builder undo · /il builder cancel","§7Fabric: B opens the room editor"));item.setItemMeta(meta);if(tool(p)!=null)p.getInventory().setItemInMainHand(item);else{int slot=-1;for(int i=0;i<9;i++)if(p.getInventory().getItem(i)==null||p.getInventory().getItem(i).getType().isAir()){slot=i;break;}if(slot<0)throw new IllegalArgumentException("Make an empty hotbar slot for the builder tool.");p.getInventory().setItem(slot,item);p.getInventory().setHeldItemSlot(slot);}state(p).first=null;changed(p);p.sendMessage(prompt(p));}
    private Runnable checkpoint(Player p){var room=plugin.getRoomManager().checkpoint(p);var selection=plugin.getSelectionManager().checkpoint(p);var props=plugin.getPropManager().checkpoint(p);var diversity=plugin.getDiversityManager().checkpoint(p);State st=state(p);var regions=List.copyOf(st.regions);var first=st.first;String selected=st.selected;return ()->{room.run();selection.run();props.run();diversity.run();st.regions.clear();st.regions.addAll(regions);st.first=first;st.selected=selected;};}
    private void remember(Player p,Runnable restore){State s=state(p);s.undo.push(restore);while(s.undo.size()>32)s.undo.removeLast();s.redo.clear();changed(p);}
    public void undo(Player p,boolean redo){admin(p);State s=state(p);Deque<Runnable> source=redo?s.redo:s.undo,dest=redo?s.undo:s.redo;if(source.isEmpty())throw new IllegalArgumentException(redo?"Nothing to redo.":"Nothing to undo.");Runnable present=checkpoint(p),restore=source.peek();restore.run();source.pop();dest.push(present);changed(p);}
    public void cancel(Player p){admin(p);remember(p,checkpoint(p));plugin.getSelectionManager().clearPending(p);plugin.getPropManager().restartCorner(p);try{plugin.getDiversityManager().restartCorner(p,false);plugin.getDiversityManager().restartCorner(p,true);}catch(IllegalArgumentException ignored){}state(p).first=null;p.sendMessage("Incomplete corner selection cancelled. Completed areas remain.");}
    public void clear(Player p){states.remove(p.getUniqueId());plugin.getSelectionManager().clearPending(p);plugin.getSelectionManager().clearStagedConnections(p);plugin.getSelectionManager().clearStagedVariations(p);plugin.getPropManager().clear(p);plugin.getDiversityManager().clear(p);plugin.getRoomManager().clearSelection(p);}
    public boolean handle(Player p,Action action,Block block){String kind=tool(p);if(kind==null)return false;if(action!=Action.LEFT_CLICK_BLOCK&&action!=Action.RIGHT_CLICK_BLOCK)return false;try{admin(p);if(block==null)return true;if(block.getWorld()!=p.getWorld()||block.getLocation().distanceSquared(p.getLocation())>256)throw new IllegalArgumentException("Select a nearby block in your current world.");Runnable before=checkpoint(p);boolean left=action==Action.LEFT_CLICK_BLOCK;
        if(kind.equals("room")){if(left)plugin.getRoomManager().clearSelection(p);else if(plugin.getRoomManager().point1(p).isEmpty())throw new IllegalArgumentException("Left-click the first room corner first.");plugin.getSelectionManager().clearStagedConnections(p);plugin.getSelectionManager().clearStagedVariations(p);plugin.getPropManager().clear(p);plugin.getDiversityManager().clear(p);state(p).regions.clear();state(p).first=null;plugin.getSelectionManager().handle(p,action,block);}
        else if(Set.of("shelf","table","seat").contains(kind)){region(p,kind,left,block);}
        else{boolean first;if(kind.equals("decoration")){if(left)plugin.getPropManager().restartCorner(p);first=plugin.getPropManager().hasCorner(p);}
            else if(kind.startsWith("diversity")){boolean connection=kind.equals("diversity_connection");if(left)plugin.getDiversityManager().restartCorner(p,connection);first=plugin.getDiversityManager().hasCorner(p,connection);}
            else{if(left)plugin.getSelectionManager().restartCorner(p,kind);first=plugin.getSelectionManager().hasCorner(p,kind);}
            if(!left&&!first)throw new IllegalArgumentException("Left-click the first corner before right-clicking the second.");
            if(kind.equals("decoration"))plugin.getPropManager().handle(p,action,block);else if(kind.startsWith("diversity"))plugin.getDiversityManager().handle(p,action,block);else plugin.getSelectionManager().handle(p,action,block);
        }
        remember(p,before);
    }catch(RuntimeException ex){p.sendMessage("§c"+Objects.requireNonNullElse(ex.getMessage(),"Selection failed."));}return true;}
    private void region(Player p,String kind,boolean left,Block block){var bounds=plugin.getRoomManager().selectionBounds(p);Vector3i point=Vector3i.from(block.getLocation());if(point.x()<bounds.min().x()||point.y()<bounds.min().y()||point.z()<bounds.min().z()||point.x()>bounds.max().x()||point.y()>bounds.max().y()||point.z()>bounds.max().z())throw new IllegalArgumentException("Region corners must be inside the selected room.");State s=state(p);if(left){s.first=point;p.sendMessage("First "+kind+" corner set. Right-click the other corner.");return;}if(s.first==null)throw new IllegalArgumentException("Left-click the first corner first.");Vector3i min=min(s.first,point),max=max(s.first,point),size=max.subtract(min).add(new Vector3i(1,1,1));s.regions.add(new RoomRegion(kind,min.subtract(bounds.min()),size,s.category));s.first=null;p.sendMessage("Region staged. Save the room, or /il builder apply to mark this source build.");}
    public void load(Player p,String id){admin(p);var room=plugin.getRoomManager().getActive(id).orElseThrow(()->new IllegalArgumentException("Active room not found."));var b=plugin.getRoomManager().selectionBounds(p);if(!b.max().subtract(b.min()).add(new Vector3i(1,1,1)).equals(room.size()))throw new IllegalArgumentException("Select authoring bounds matching this room's dimensions first.");Runnable before=checkpoint(p);plugin.getSelectionManager().loadStaging(p,room);plugin.getPropManager().loadStaging(p,room);plugin.getDiversityManager().load(p,id);state(p).regions.clear();state(p).regions.addAll(room.regions());state(p).selected=id;remember(p,before);}
    public void saved(Player p,String id){State s=state(p);s.selected=id;s.undo.clear();s.redo.clear();changed(p);}
    public void apply(Player p){
        admin(p);var bounds=plugin.getRoomManager().selectionBounds(p);var previous=new ArrayList<>(applied);
        for(var region:regions(p)){Vector3i lo=bounds.min().add(region.min()),hi=lo.add(region.size()).subtract(new Vector3i(1,1,1));var mark=new Mark(p.getWorld().getName(),region.kind(),lo,hi);if(!applied.contains(mark))applied.add(mark);}
        try{saveApplied();}catch(RuntimeException ex){applied.clear();applied.addAll(previous);throw ex;}
        for(var region:regions(p))if(region.kind().equals("shelf")){Vector3i lo=bounds.min().add(region.min()),hi=lo.add(region.size()).subtract(new Vector3i(1,1,1));for(int x=lo.x();x<=hi.x();x++)for(int y=lo.y();y<=hi.y();y++)for(int z=lo.z();z<=hi.z();z++){if(!p.getWorld().isChunkLoaded(x>>4,z>>4))continue;Block block=p.getWorld().getBlockAt(x,y,z);if(block.getType()==Material.CHISELED_BOOKSHELF){plugin.getBookStorageManager().setShelfCategory(block.getLocation(),region.category());plugin.getBookStorageManager().populateBookshelf(block);}}}
        state(p).undo.clear();state(p).redo.clear();changed(p);
    }
    public void generated(Room room,PlacedRoom instance,String world){List<Mark> list=new ArrayList<>();for(var region:room.regions()){Vector3i a=instance.transform().transform(region.min(),room.size()).add(instance.origin()),b=instance.transform().transform(region.min().add(region.size()).subtract(new Vector3i(1,1,1)),room.size()).add(instance.origin());list.add(new Mark(world,region.kind(),min(a,b),max(a,b)));}generated.put(instance.instanceId(),list);}
    public boolean reading(org.bukkit.Location l,String kind){Vector3i p=Vector3i.from(l);return java.util.stream.Stream.concat(applied.stream(),generated.values().stream().flatMap(Collection::stream)).anyMatch(m->m.world().equals(l.getWorld().getName())&&m.kind().equals(kind)&&p.x()>=m.min().x()&&p.y()>=m.min().y()&&p.z()>=m.min().z()&&p.x()<=m.max().x()&&p.y()<=m.max().y()&&p.z()<=m.max().z());}
    public List<Box> boxes(Player p){List<Box> out=new ArrayList<>();var a=plugin.getRoomManager().point1(p);var b=plugin.getRoomManager().point2(p);if(a.isPresent()&&b.isPresent()){Vector3i lo=min(a.get(),b.get()),hi=max(a.get(),b.get());out.add(new Box("room","Room bounds",lo,hi,0x40c9ff));for(var cp:plugin.getSelectionManager().stagedConnections(p)){var cells=cp.cells();Vector3i c=lo.add(cells.getFirst()),d=lo.add(cells.getLast());out.add(new Box("connection",cp.id()+" "+cp.direction()+" "+cp.width()+"x"+cp.height(),min(c,d),max(c,d),0x54ed84));}for(var v:plugin.getSelectionManager().stagedVariations(p)){if(!v.blocks().isEmpty()){Vector3i loV=v.blocks().stream().map(com.infinitylibrary.model.RoomBlock::position).reduce(AuthoringManager::min).orElseThrow(),hiV=v.blocks().stream().map(com.infinitylibrary.model.RoomBlock::position).reduce(AuthoringManager::max).orElseThrow();out.add(new Box("variation",v.id()+" ["+v.category()+"]",lo.add(loV),lo.add(hiV),0x78e5d8));}}for(var area:plugin.getPropManager().previewAreas(p))out.add(new Box("decoration",area.id()+" ["+area.category()+"]",lo.add(area.min()),lo.add(area.min()).add(area.size()).subtract(new Vector3i(1,1,1)),0xffcf4a));for(var area:plugin.getDiversityManager().previewAreas(p))out.add(new Box("diversity",area.id(),lo.add(area.min()),lo.add(area.min()).add(area.size()).subtract(new Vector3i(1,1,1)),0xdc7bff));for(var region:regions(p))out.add(new Box(region.kind(),region.kind()+" "+region.category(),lo.add(region.min()),lo.add(region.min()).add(region.size()).subtract(new Vector3i(1,1,1)),0xff8b62));}
        else a.ifPresent(v->out.add(new Box("corner","First room corner",v,v,0x40c9ff)));
        String tool=tool(p);Optional<Vector3i> first=Optional.empty();if(tool!=null&&!tool.equals("room")){if(Set.of("shelf","table","seat").contains(tool))first=Optional.ofNullable(state(p).first);else if(tool.equals("decoration"))first=plugin.getPropManager().firstCorner(p).map(v->a.isPresent()&&b.isPresent()?min(a.get(),b.get()).add(v):v);else if(tool.startsWith("diversity")){first=plugin.getDiversityManager().firstCornerWorld(p,tool.equals("diversity_connection"));}else first=plugin.getSelectionManager().firstCorner(p,tool).map(v->a.isPresent()&&b.isPresent()?min(a.get(),b.get()).add(v):v);}
        plugin.getDiversityManager().sourceBox(p).ifPresent(out::add);
        first.ifPresent(v->out.add(new Box("corner","First "+tool+" corner",v,v,0xffffff)));return out.stream().limit(192).toList();}
    private static Vector3i min(Vector3i a,Vector3i b){return new Vector3i(Math.min(a.x(),b.x()),Math.min(a.y(),b.y()),Math.min(a.z(),b.z()));}private static Vector3i max(Vector3i a,Vector3i b){return new Vector3i(Math.max(a.x(),b.x()),Math.max(a.y(),b.y()),Math.max(a.z(),b.z()));}
}
